{
  "name": "node-module-resolver",
  "version": "0.0.0",
  "description": "Programmatic module resolution for a build tool, delegating to Node's own algorithm",
  "type": "module",
  "main": "./src/index.js",
  "exports": {
    ".": "./src/index.js"
  },
  "files": [
    "src"
  ],
  "scripts": {
    "test": "node --test",
    "lint": "node --check src/index.js && node --check src/resolver.js"
  },
  "engines": {
    "node": ">=18.17"
  },
  "private": true,
  "license": "MIT"
}

import { createRequire } from 'node:module'
import { pathToFileURL } from 'node:url'

function toAnchor(parent) {
  if (parent instanceof URL) return parent.href
  return pathToFileURL(parent).href
}

/**
 * Create a resolver anchored at `parent` that follows Node's own module
 * resolution algorithm (the same one behind `require.resolve`).
 *
 * @param {string | URL} [parent] Absolute file path or `file:` URL used as the
 *   resolution anchor. Defaults to the current working directory.
 * @returns {{
 *   resolve: (specifier: string) => string,
 *   resolvePaths: (specifier: string, paths: string[]) => string,
 *   require: NodeRequire,
 * }}
 */
export function createResolver(parent = `${process.cwd()}/`) {
  const require = createRequire(toAnchor(parent))

  return {
    resolve(specifier) {
      return require.resolve(specifier)
    },
    resolvePaths(specifier, paths) {
      return require.resolve(specifier, { paths })
    },
    require,
  }
}

/**
 * Resolve a single `specifier` as if it were required from `parent`.
 *
 * @param {string} specifier
 * @param {string | URL} [parent]
 * @returns {string}
 */
export function resolve(specifier, parent) {
  return createResolver(parent).resolve(specifier)
}

import test from 'node:test'
import assert from 'node:assert/strict'
import { fileURLToPath, pathToFileURL } from 'node:url'
import { dirname, join } from 'node:path'
import { createResolver, resolve } from '../src/index.js'

const here = dirname(fileURLToPath(import.meta.url))
const app = join(here, 'fixtures/app/index.js')

test('resolves Node builtins', () => {
  const r = createResolver(app)
  assert.equal(r.resolve('fs'), 'fs')
  assert.equal(r.resolve('node:path'), 'node:path')
})

test('resolves a relative path against the anchor', () => {
  const r = createResolver(app)
  assert.equal(r.resolve('./local.js'), join(here, 'fixtures/app/local.js'))
})

test('resolves a package main from node_modules', () => {
  const r = createResolver(app)
  assert.equal(
    r.resolve('dep'),
    join(here, 'fixtures/app/node_modules/dep/lib/main.js'),
  )
})

test('honors the "require" condition in package exports', () => {
  const r = createResolver(app)
  assert.equal(
    r.resolve('esm-dep'),
    join(here, 'fixtures/app/node_modules/esm-dep/cjs.js'),
  )
})

test('resolve() accepts a file URL anchor', () => {
  assert.equal(
    resolve('dep', pathToFileURL(app)),
    join(here, 'fixtures/app/node_modules/dep/lib/main.js'),
  )
})
